 private const string Op="11111111111111111111111111111111";
 private static readonly DateTimeOffset Now=DateTimeOffset.UtcNow.AddMinutes(-10);
 private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 private static readonly AdminJobScope Scope=new("T001",["customer-two"]);
 private static async Task<DurableJobRecord> Seed(InMemoryJobRepository repo,string id="job-queued",string tenant="T001",string customer="customer-one",string name="document-processing")
 {var security=new TrustedSecurityContext(new("customer-owner","CUSTOMER",Now,"original-customer-session"),new("workspace","local-uat-workspace:"+tenant),new("customer-advice","original-consent","original-decision",customer));var result=await repo.ScheduleAsync(new("ScheduleJob","1.0.0","key-"+id,"fingerprint-"+id,"request-"+id,"correlation-"+id,null,security,id,name,"Document Intelligence Service","private-document-reference",customer,Now,Now),default);return result.Job;}
 private static async Task<DurableJobRecord> Failed(InMemoryJobRepository repo,string id="job-retry",bool retryable=true)
 {await Seed(repo,id);var lease=await repo.ClaimAsync(id,"worker-one",Now,TimeSpan.FromMinutes(1),default);return await repo.FailClaimAsync(lease!,"job.document-processing.owner-unavailable",retryable,retryable?Now.AddHours(1):null,Now.AddSeconds(1),default);}
 private static AdminJobChange Change(DurableJobRecord row,string action="cancel",string op=Op)=>new(op,JobAdministration.Revision(row),action,"Reviewed operational recovery");
 [Fact]public async Task FullQueueCancelRetryAttemptsHistoryAndExactRecoveryPreserveOriginalCustomerAuthority()
 {
  await using var h=await Host.Start();var page=await h.Client.GetFromJsonAsync<AdminJobPage>("");Assert.Equal(2,page!.Matching);Assert.Equal(1,page.Counts.Queued);Assert.Equal(1,page.Counts.Retrying);
  var queued=(await h.Repository.GetAsync("job-queued",default))!;var cancellation=await h.Client.PostAsJsonAsync("job-queued/changes",Change(queued));Assert.Equal(HttpStatusCode.OK,cancellation.StatusCode);var cancelled=await cancellation.Content.ReadFromJsonAsync<AdminJobReceipt>();Assert.Equal("CANCELLED",cancelled!.After.State);Assert.False(cancelled.After.CancellationPending);
  var source=(await h.Repository.GetAsync("job-retry",default))!;var change=Change(source,"retry","22222222222222222222222222222222");var retry=await h.Client.PostAsJsonAsync("job-retry/changes",change);Assert.Equal(HttpStatusCode.OK,retry.StatusCode);var receipt=await retry.Content.ReadFromJsonAsync<AdminJobReceipt>();Assert.Equal("RETRYING",receipt!.After.State);Assert.Equal(1,receipt.After.ReplayCount);Assert.Equal(2,h.Policy.Contexts.Count);Assert.All(h.Policy.Contexts,x=>Assert.Equal(source.Security,x));
  var after=(await h.Repository.GetAsync("job-retry",default))!;Assert.Equal(source.Security,after.Security);var lease=await h.Repository.ClaimAsync("job-retry","worker-two",DateTimeOffset.UtcNow,TimeSpan.FromMinutes(1),default);var target=new Target();var app=new JobManagementApplication(h.Repository,new CapturingTelemetry(),TimeProvider.System);await app.ExecuteClaimedAsync(lease!,h.Policy,h.Policy,target,default);Assert.Equal(source.Security,target.Received!.Security);Assert.Equal(JobState.Completed,(await h.Repository.GetAsync("job-retry",default))!.State);
  h.Policy.Deny=true;var replay=await h.Client.PostAsJsonAsync("job-retry/changes",change);Assert.Equal(HttpStatusCode.OK,replay.StatusCode);Assert.Equal(receipt,await replay.Content.ReadFromJsonAsync<AdminJobReceipt>());Assert.Single((await h.Repository.HistoryAdminAsync(Scope,"job-retry",null,default)).Items);
  var attempts=await h.Client.GetFromJsonAsync<AdminJobAttempts>("job-retry/attempts");Assert.Equal([2,1],attempts!.Items.Select(x=>x.Attempt));var exact=await h.Client.GetFromJsonAsync<AdminJobReceipt>("job-retry/changes/"+change.OperationId);Assert.Equal(receipt,exact);
  var json=await h.Client.GetStringAsync("job-retry");foreach(var secret in new[]{"original-customer-session","original-consent","original-decision","leaseToken","security","payloadReference"})Assert.DoesNotContain(secret,json,StringComparison.OrdinalIgnoreCase);Assert.Equal("no-store",retry.Headers.CacheControl?.ToString());
 }
 [Fact]public async Task SelectedDocumentRecoveryQueueUsesExactTenantCustomerAndVersionWithStableScope(){await using var h=await Host.Start();await Seed(h.Repository,"job-different-document",name:"background-other");var page=await h.Client.GetFromJsonAsync<AdminJobPage>("?customerId=customer-one&documentVersionId=private-document-reference");Assert.Equal(2,page!.Matching);Assert.All(page.Items,row=>Assert.Equal("private-document-reference",row.DocumentVersionId));Assert.Empty((await h.Client.GetFromJsonAsync<AdminJobPage>("?documentVersionId=other-version"))!.Items);Assert.Equal(HttpStatusCode.BadRequest,(await h.Client.GetAsync("?documentVersionId=bad%20id")).StatusCode);}
 [Theory][InlineData(JobState.Scheduled,0,false,false,false,"QUEUED")][InlineData(JobState.Scheduled,1,false,false,false,"RETRYING")][InlineData(JobState.Running,0,false,false,false,"PROCESSING")][InlineData(JobState.CancellationRequested,0,false,false,false,"PROCESSING")][InlineData(JobState.Completed,0,false,false,false,"COMPLETED")][InlineData(JobState.Failed,0,false,false,false,"FAILED")][InlineData(JobState.Failed,0,true,true,false,"RETRYING")][InlineData(JobState.Failed,0,true,true,true,"FAILED")][InlineData(JobState.Cancelled,0,false,false,false,"CANCELLED")]
 public async Task AllRequiredBusinessStatesRetainOwnerMeaning(JobState state,int replays,bool retryable,bool next,bool reconcile,string expected){var row=await Seed(new());row=row with{State=state,ReplayCount=replays,Retryable=retryable,NextAttemptAt=next?Now.AddHours(1):null,ReconciliationRequired=reconcile};Assert.Equal(expected,JobAdministration.State(row));var summary=JobAdministration.Summary(Scope,row);Assert.Equal(state==JobState.CancellationRequested,summary.CancellationPending);if(reconcile)Assert.False(summary.CanRetry||summary.CanCancel);}
 [Fact]public async Task RunningCancellationRetainsUnknownOutcomeUntilOwnerConfirmsCancellation()
 {await using var h=await Host.Start();var lease=await h.Repository.ClaimAsync("job-queued","worker",Now,TimeSpan.FromMinutes(1),default);var row=(await h.Repository.GetAsync("job-queued",default))!;var r=await h.Client.PostAsJsonAsync("job-queued/changes",Change(row));var receipt=await r.Content.ReadFromJsonAsync<AdminJobReceipt>();Assert.Equal(HttpStatusCode.OK,r.StatusCode);Assert.Equal("PROCESSING",receipt!.After.State);Assert.True(receipt.After.CancellationPending);Assert.False(receipt.After.CanCancel);await h.Repository.FailClaimAsync(lease!,"owner.cancelled",false,null,DateTimeOffset.UtcNow,default);var unknown=(await h.Client.GetFromJsonAsync<AdminJobSummary>("job-queued"))!;Assert.Equal("PROCESSING",unknown.State);Assert.True(unknown.NeedsOwnerReview);Assert.False(unknown.CanRetry||unknown.CanCancel);await h.Repository.ReconcileAsync(row.JobId,row.CustomerId,JobReconciliationOutcome.ConfirmedCancelled,DateTimeOffset.UtcNow,default);Assert.Equal("CANCELLED",(await h.Client.GetFromJsonAsync<AdminJobSummary>("job-queued"))!.State);}
