 [Fact]public async Task TenantProofCustomerBindingAndLegacyContextCannotLeakJobs(){await using var h=await Host.Start();await Seed(h.Repository,"forged-customer","T001","customer-two");await Seed(h.Repository,"legacy",name:"engineering-fixture");var legacy=(await h.Repository.GetAsync("legacy",default))!;Assert.True(Scope.Owns(legacy));var source=legacy with{Security=legacy.Security with{Workload=new("fixture","unbound-workload")}};Assert.False(Scope.Owns(source));foreach(var id in new[]{"job-other","forged-customer"}){Assert.Equal(HttpStatusCode.NotFound,(await h.Client.GetAsync(id)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await h.Client.GetAsync(id+"/attempts")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await h.Client.GetAsync(id+"/history")).StatusCode);}var page=await h.Client.GetFromJsonAsync<AdminJobPage>("");Assert.DoesNotContain(page!.Items,x=>x.JobId is "job-other" or "forged-customer");h.Client.DefaultRequestHeaders.Remove("X-Monergy-Tenant");h.Client.DefaultRequestHeaders.Add("X-Monergy-Tenant","T002");Assert.Equal(HttpStatusCode.NotFound,(await h.Client.GetAsync("job-queued")).StatusCode);}
 [Fact]public async Task NewCustomerWithoutStaticBindingStillRequiresPersistedExactTenantContext(){var r=new InMemoryJobRepository();var row=await Seed(r,customer:"new-customer");Assert.True(Scope.Owns(row));Assert.False(Scope.Owns(row with{Security=row.Security with{Access=row.Security.Access with{CustomerId="other"}}}));Assert.Single((await r.ListAdminAsync(Scope,new(CustomerId:"new-customer"),default)).Items);Assert.Empty((await r.ListAdminAsync(new("T002",[]),new(),default)).Items);}
 [Fact]public async Task StaleRevisionChangedOperationActorAndJobReuseRejectWithoutAnotherEffect(){var r=new InMemoryJobRepository();var job=await Seed(r);var other=await Seed(r,"job-two");var change=Change(job);await r.ChangeAdminAsync(Scope,"A900",job.JobId,change,Now,default);foreach(var c in new[]{change with{Reason="Another"},change with{Action="retry"}})Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAdminAsync(Scope,"A900",job.JobId,c,Now,default))).Status);Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAdminAsync(Scope,"A901",job.JobId,change,Now,default))).Status);Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAdminAsync(Scope,"A900",other.JobId,change,Now,default))).Status);Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAdminAsync(Scope,"A900",job.JobId,change with{OperationId=Guid.NewGuid().ToString("N")},Now,default))).Status);Assert.Single((await r.HistoryAdminAsync(Scope,job.JobId,null,default)).Items);}
 [Fact]public async Task ConcurrentIdenticalRecoveryCommitsOnceAndWorkerStateChangeRejectsStaleReview(){var r=new InMemoryJobRepository();var job=await Seed(r);var values=await Task.WhenAll(Enumerable.Range(0,5).Select(_=>r.ChangeAdminAsync(Scope,"A900",job.JobId,Change(job),Now,default)));Assert.All(values,x=>Assert.Equal(values[0],x));Assert.Single((await r.HistoryAdminAsync(Scope,job.JobId,null,default)).Items);var next=await Seed(r,"racing-worker");await r.ClaimAsync(next.JobId,"worker",Now,TimeSpan.FromMinutes(1),default);Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAdminAsync(Scope,"A900",next.JobId,Change(next,op:Guid.NewGuid().ToString("N")),Now,default))).Status);}
 [Fact]public async Task FailedRetryStillRequiresOriginalCustomerPermissionAndNeverReplacesTheActor(){await using var h=await Host.Start();h.Policy.Deny=true;var raw=(await h.Repository.GetAsync("job-retry",default))!;var response=await h.Client.PostAsJsonAsync("job-retry/changes",Change(raw,"retry"));Assert.Equal(HttpStatusCode.Conflict,response.StatusCode);Assert.Empty((await h.Repository.HistoryAdminAsync(Scope,"job-retry",null,default)).Items);Assert.Equal(raw.Security,(await h.Repository.GetAsync(raw.JobId,default))!.Security);Assert.All(h.Policy.Contexts,x=>Assert.Equal("customer-owner",x.Actor.ActorId));}
