 [Fact]public async Task CancelledCompletedNonRetryableUnknownTargetAndUnknownOutcomeDoNotPermitRetry(){var r=new InMemoryJobRepository();var failed=await Failed(r,retryable:false);Assert.False(JobAdministration.Summary(Scope,failed).CanRetry);Assert.Equal(409,(await Assert.ThrowsAsync<TenantBoundaryException>(()=>r.ChangeAdminAsync(Scope,"A900",failed.JobId,Change(failed,"retry"),Now,default))).Status);var raw=await Seed(r,"unknown");var unknown=raw with{JobName="unregistered",State=JobState.Failed,Retryable=true};Assert.False(JobAdministration.CanRetry(unknown));foreach(var state in new[]{JobState.Completed,JobState.Cancelled})Assert.False(JobAdministration.CanRetry(raw with{State=state,Retryable=true}));var uncertain=failed with{Retryable=true,ReconciliationRequired=true};Assert.False(JobAdministration.CanRetry(uncertain));Assert.False(JobAdministration.CanCancel(uncertain));Assert.False(JobAdministration.Summary(Scope with{AllowRetry=false},failed with{Retryable=true}).CanRetry);}
 [Fact]public async Task FiftyItemQueueAttemptAndHistoryPagesRetainAllVersions(){var r=new InMemoryJobRepository();for(var i=0;i<112;i++)await Seed(r,"page-"+i.ToString("D3",CultureInfo.InvariantCulture));var page=await r.ListAdminAsync(Scope,new(),default);Assert.Equal(50,page.Items.Count);Assert.Equal(112,page.Matching);var next=await r.ListAdminAsync(Scope,new(After:page.NextCursor),default);Assert.Equal(50,next.Items.Count);var last=await r.ListAdminAsync(Scope,new(After:next.NextCursor),default);Assert.Equal(12,last.Items.Count);Assert.Null(last.NextCursor);var row=await Failed(r);AdminJobReceipt? first=null;for(var i=0;i<111;i++){row=(await r.GetAsync(row.JobId,default))!;var time=Now.AddMilliseconds(i);var receipt=await r.ChangeAdminAsync(Scope,"A900",row.JobId,Change(row,"retry",(i+1).ToString("x32",CultureInfo.InvariantCulture)),time,default);first??=receipt;var lease=await r.ClaimAsync(row.JobId,"worker",time,TimeSpan.FromMinutes(1),default);await r.FailClaimAsync(lease!,"retry.failure",true,time.AddHours(1),time.AddMilliseconds(1),default);}var history=await r.HistoryAdminAsync(Scope,row.JobId,null,default);Assert.Equal(50,history.Items.Count);Assert.Equal(50,(await r.HistoryAdminAsync(Scope,row.JobId,history.NextBeforeId,default)).Items.Count);Assert.Equal(first,await r.ReceiptAdminAsync(Scope,row.JobId,first!.OperationId,default));var attempts=await r.AttemptsAdminAsync(Scope,row.JobId,null,default);Assert.Equal(50,attempts.Items.Count);Assert.Equal(112,attempts.Items[0].Attempt);Assert.Equal(62,(await r.AttemptsAdminAsync(Scope,row.JobId,attempts.NextBeforeAttempt,default)).Items[0].Attempt);}
