 private sealed class Target:IJobExecutionTarget{public DurableJobRecord? Received;public Task<JobExecutionResult> ExecuteAsync(DurableJobRecord job,CancellationToken ct){Received=job;return Task.FromResult(JobExecutionResult.Completed("owner-result"));}}
 private sealed class Policy:IJobAuthorizationPolicy,IJobConsentDecisionPort
 {public bool Deny,Unavailable;public List<TrustedSecurityContext> Contexts=[];public Task<ContractError?> AuthorizeAsync(TrustedSecurityContext context,DurableJobRecord job,string correlationId,CancellationToken cancellationToken)=>EvaluateAsync(context,job,correlationId,cancellationToken);public Task<ContractError?> EvaluateAsync(TrustedSecurityContext context,DurableJobRecord job,string correlationId,CancellationToken cancellationToken){Contexts.Add(context);return Task.FromResult<ContractError?>(Deny||Unavailable?new("job.permission.denied",Unavailable?ContractErrorCategory.DependencyFailure:ContractErrorCategory.AccessDenied,"Current original customer permission is required",Unavailable,correlationId):null);}}
 private sealed class Authority:HttpMessageHandler
 {public int Calls,Status=200,DenyAfter=int.MaxValue,ChangeAfter=int.MaxValue;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;var status=Calls>DenyAfter?403:Status;return Task.FromResult(new HttpResponseMessage((HttpStatusCode)status){Content=JsonContent.Create(status==200?(object)new TenantAdminContext(request.Headers.GetValues("X-Monergy-Tenant").Single(),Calls>ChangeAfter?"A901":"A900",1,"TenantAdmin"):new{error="ADMINISTRATOR_REQUIRED"})});}}
 private sealed class Corrupt(IJobAdministrationRepository inner,string mode):IJobAdministrationRepository
 {public async Task<AdminJobPage> ListAdminAsync(AdminJobScope scope,AdminJobQuery query,CancellationToken ct){var p=await inner.ListAdminAsync(scope,query,ct);return mode=="list"?p with{Items=[p.Items[0]with{TenantId="foreign"}]}:p;}public Task<AdminJobSummary?> ReadAdminAsync(AdminJobScope scope,string jobId,CancellationToken ct)=>inner.ReadAdminAsync(scope,jobId,ct);public Task<AdminJobAttempts> AttemptsAdminAsync(AdminJobScope scope,string jobId,int? before,CancellationToken ct)=>inner.AttemptsAdminAsync(scope,jobId,before,ct);public async Task<AdminJobReceipt> ChangeAdminAsync(AdminJobScope scope,string actor,string jobId,AdminJobChange change,DateTimeOffset now,CancellationToken ct){var r=await inner.ChangeAdminAsync(scope,actor,jobId,change,now,ct);return mode=="mutation"?r with{After=r.After with{CustomerId="other"}}:r;}public async Task<AdminJobReceipt?> ReceiptAdminAsync(AdminJobScope scope,string jobId,string operation,CancellationToken ct){var r=await inner.ReceiptAdminAsync(scope,jobId,operation,ct);return mode=="readback"&&r is not null?r with{Reason="forged"}:r;}public Task<AdminJobHistory> HistoryAdminAsync(AdminJobScope scope,string jobId,string? before,CancellationToken ct)=>inner.HistoryAdminAsync(scope,jobId,before,ct);}
 private sealed class Host(WebApplication app,HttpClient client,InMemoryJobRepository repository,Authority authority,Policy policy):IAsyncDisposable
 {public HttpClient Client=>client;public InMemoryJobRepository Repository=>repository;public Authority Authority=>authority;public Policy Policy=>policy;public static async Task<Host> Start(string? corrupt=null){var repo=new InMemoryJobRepository();await Seed(repo);await Failed(repo);await Seed(repo,"job-other","T002","customer-two");var authority=new Authority();var policy=new Policy();var builder=WebApplication.CreateBuilder();builder.Logging.ClearProviders();builder.WebHost.UseUrls("http://127.0.0.1:0");var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Monergy:ExecutionZone","CI_EPHEMERAL"}}).Build();builder.Services.AddSingleton(new TenantAccessClient(config,new HttpClient(authority)));builder.Services.AddSingleton(new TenantBoundaryOptions{Service="job-management",CapabilityPrefix="job-management.",ProbeUrl="http://127.0.0.1:5118/",CustomerTenants=new Dictionary<string,string>{{"customer-one","T001"},{"customer-two","T002"}}});builder.Services.AddSingleton<IJobRepository>(repo);builder.Services.AddSingleton<IJobAdministrationRepository>(corrupt is null?repo:new Corrupt(repo,corrupt));builder.Services.AddSingleton<IJobAuthorizationPolicy>(policy);builder.Services.AddSingleton<IJobConsentDecisionPort>(policy);var app=builder.Build();app.MapJobAdministration();await app.StartAsync();var root=app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single();var client=new HttpClient{BaseAddress=new Uri(root+"/local/v1/administration/processing/")};client.DefaultRequestHeaders.Add("X-Monergy-Tenant","T001");client.DefaultRequestHeaders.Add("X-Monergy-Session","admin-session");return new(app,client,repo,authority,policy);}public async ValueTask DisposeAsync(){client.Dispose();await app.DisposeAsync();}}
}
